export const getReplayReviewerGuidanceUrl = (organizationId: string) => {
  return `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/reviewer-guidance/replay`;
};

/**
 * Run auto-review, with these words as its guidance, over the newest requests people decided, and set what it would have done against what each person did: where it agrees, what it would have let through that a person denied, and what it would have asked about that a person allowed. One model call a request. Nothing is saved. Only an administrator may ask.
 * @summary Test guidance for auto-review against recent requests
 */
export const replayReviewerGuidance = async (
  organizationId: string,
  reviewerGuidanceReplayInput: ReviewerGuidanceReplayInput,
  headers: ReplayReviewerGuidanceHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<ReviewerGuidanceReplay> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<ReviewerGuidanceReplay>(
    getReplayReviewerGuidanceUrl(organizationId),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...headers,
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(reviewerGuidanceReplayInput),
    },
  );
};

